__NUXT_JSONP__("/desarrollo-sostenible/eventos/la_adaptacion_y_resiliencia_comunitaria_ante_el_cambio_climatico_retos_y_recomendaciones", (function(a,b,c,d,e,f,g){return {data:[{post:{slug:"la_adaptacion_y_resiliencia_comunitaria_ante_el_cambio_climatico_retos_y_recomendaciones",title:"La adaptación y resiliencia comunitaria ante el cambio climático: retos y recomendaciones",date:"2024-09-02T18:59:05.146Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd4b4d42d-e0df-48f8-b304-d9c0bde0feba\u002F",autor:"Ethos",category:"desarrollo-sostenible",extracto:"A partir del trabajo con comunidades locales, Ethos elaboró un policy brief con los principales retos y recomendaciones para impulsar la resiliencia comunitaria ante el cambio climático.",galeria:null,toc:[],body:{type:"root",children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En México, vivimos un panorama preocupante respecto al cambio climático: 71% del territorio nacional es vulnerable a sus efectos y de los 2,552 municipios que tenemos, 1,804 están amenazados por fenómenos como el aumento de temperatura, sequías, ciclones y huracanes; es decir, a nivel local se resienten de inmediato sus consecuencias que, además de poner en riesgo la biodiversidad y los recursos naturales, amenazan la seguridad hídrica y alimentaria, la infraestructura, la salud pública y los medios de vida de millones de personas. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Frente a este contexto, en los últimos años, desde Ethos Innovación en Políticas Públicas hemos trabajado temas de adaptación al cambio climático en comunidades rurales y costeras de Yucatán, Sinaloa, Puebla, Chiapas y Oaxaca. Esto nos ha permitido conocer de primera mano los desafíos que enfrentan y a partir de ello, elaborar recomendaciones que hemos reunido en el "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" "},{type:b,tag:"a",props:{href:"https:\u002F\u002Fwww.ethos.org.mx\u002Fdesarrollo-sostenible\u002Fpublicaciones\u002Fcomunidades_adaptacion_y_resiliencia_ante_el_cambio_climatico_en_mexico_retos_y_recomendaciones_a_partir_de_nueve_casos_de_estudio_en_zonas_rurales_y_costeras",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:"«Comunidades, adaptación y resiliencia ante el cambio climático en México: retos y recomendaciones a partir de nueve casos de estudio en zonas rurales y costeras»"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Así, desde el año 2021, de la mano de organizaciones como Environmental Defense Fund (EDF) y el World Resources Institute (WRI) México, impulsamos nueve proyectos con organizaciones locales relacionados con la adaptación y resiliencia ante el cambio climático, los cuales nos permitieron percatarnos que uno de los grandes desafíos que enfrentan es la falta de acceso a financiamiento adecuado."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Otro tema preocupante es el carácter incierto de las proyecciones climáticas, que genera dudas sobre la viabilidad de las soluciones de adaptación propuestas por las organizaciones locales, las cuales se enfocan en resolver problemas inmediatos ante eventos climáticos adversos, limitando así su impacto en el mediano y largo plazo. Asimismo, sus soluciones de adaptación suelen ser limitadas geográfica y temáticamente."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ante esta situación, consideramos indispensable involucrar a nuevos sectores, fomentar el acceso al financiamiento, empoderar a actores locales y generar más evidencias a partir de casos existentes. Esto mejoraría la efectividad y sostenibilidad de los proyectos, permitiendo una respuesta más robusta y coordinada a los desafíos del cambio climático en México. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En este "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" se encuentran detallados estos y otros hallazgos de la sistematización y análisis de los casos de las nueve comunidades en las que estuvimos presentes, incluyendo los retos y recomendaciones que surgieron a partir de esta experiencia."}]},{type:a,value:c}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fla_adaptacion_y_resiliencia_comunitaria_ante_el_cambio_climatico_retos_y_recomendaciones",extension:".md",createdAt:g,updatedAt:g}}],fetch:{},mutations:[]}}("text","element","\n","p","em","policy brief","2024-10-02T22:32:44.079Z")));